/*
 * Typing cat (middle strip, 160x84). Reacts to key presses:
 *   key on the left half  -> left paw down,  key on the right half -> right paw down
 *   no typing for SLEEP_MS -> eyes closed, zzz
 * Frames are pre-drawn images (cat_frames.c, generated by scripts/make_cat_frames.py),
 * so the screen is only redrawn when the frame actually changes.
 *
 * Threads: the key listener runs on whatever thread raised the event and only
 * updates atomics + (re)schedules a work item; all LVGL calls happen in that
 * work item, on the display work queue.
 */
#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <zmk/display.h>
#include <zmk/event_manager.h>
#include <zmk/events/position_state_changed.h>

#include <dongle_screen/dongle_screen.h>

extern const lv_img_dsc_t cat_idle, cat_left, cat_right, cat_both, cat_sleep;

#define TAP_MS 120       /* a paw stays down at least this long per key press */
#define SLEEP_MS 30000   /* fall asleep after this long without a key press */

static atomic_t held[2];          /* keys currently held per side */
static atomic_t last_press[2];    /* k_uptime_get_32() of the last press per side */
static atomic_t last_any;         /* last press on either side */

static lv_obj_t *cat_img;
static const lv_img_dsc_t *shown;
static struct k_work_delayable cat_work;

static bool paw_down(enum dongle_side side, uint32_t now, uint32_t *wait) {
    if (atomic_get(&held[side]) > 0) {
        return true;
    }
    uint32_t since = now - (uint32_t)atomic_get(&last_press[side]);
    if (since < TAP_MS) {
        *wait = MIN(*wait, TAP_MS - since);
        return true;
    }
    return false;
}

static void cat_work_cb(struct k_work *work) {
    ARG_UNUSED(work);
    if (cat_img == NULL) {
        return;
    }
    uint32_t now = k_uptime_get_32();
    uint32_t wait = UINT32_MAX;
    bool l = paw_down(DONGLE_SIDE_LEFT, now, &wait);
    bool r = paw_down(DONGLE_SIDE_RIGHT, now, &wait);
    uint32_t idle = now - (uint32_t)atomic_get(&last_any);

    const lv_img_dsc_t *frame;
    if (l || r) {
        frame = l && r ? &cat_both : l ? &cat_left : &cat_right;
    } else if (idle >= SLEEP_MS) {
        frame = &cat_sleep;
    } else {
        frame = &cat_idle;
        wait = MIN(wait, SLEEP_MS - idle);
    }

    if (frame != shown) {
        lv_img_set_src(cat_img, frame);
        shown = frame;
    }
    if (wait != UINT32_MAX) {
        k_work_reschedule_for_queue(zmk_display_work_q(), &cat_work, K_MSEC(wait));
    }
}

static int cat_listener_cb(const zmk_event_t *eh) {
    const struct zmk_position_state_changed *ev = as_zmk_position_state_changed(eh);
    if (ev == NULL || ev->position >= DONGLE_POSITION_COUNT) {
        return ZMK_EV_EVENT_BUBBLE;
    }
    enum dongle_side side = dongle_position_side(ev->position);

    if (ev->state) {
        uint32_t now = k_uptime_get_32();
        atomic_inc(&held[side]);
        atomic_set(&last_press[side], (atomic_val_t)now);
        atomic_set(&last_any, (atomic_val_t)now);
    } else if (atomic_dec(&held[side]) <= 0) {
        atomic_set(&held[side], 0); /* release without a press seen (e.g. at boot) */
    }

    if (cat_img != NULL) {
        k_work_reschedule_for_queue(zmk_display_work_q(), &cat_work, K_NO_WAIT);
    }
    return ZMK_EV_EVENT_BUBBLE;
}

ZMK_LISTENER(dongle_cat, cat_listener_cb);
ZMK_SUBSCRIPTION(dongle_cat, zmk_position_state_changed);

void dongle_cat_init(lv_obj_t *middle) {
    k_work_init_delayable(&cat_work, cat_work_cb);
    atomic_set(&last_any, (atomic_val_t)k_uptime_get_32());
    atomic_set(&last_press[DONGLE_SIDE_LEFT], (atomic_val_t)(k_uptime_get_32() - TAP_MS));
    atomic_set(&last_press[DONGLE_SIDE_RIGHT], (atomic_val_t)(k_uptime_get_32() - TAP_MS));

    cat_img = lv_img_create(middle);
    lv_img_set_src(cat_img, &cat_idle);
    shown = &cat_idle;
    lv_obj_align(cat_img, LV_ALIGN_CENTER, 0, 0);

    k_work_reschedule_for_queue(zmk_display_work_q(), &cat_work, K_NO_WAIT);
}
